const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const NOTION_TOKEN = process.env.NOTION_TOKEN;
const NOTION_DB = process.env.NOTION_MILESTONES_DB_ID;
const LINEAR_API_KEY = process.env.LINEAR_API_KEY;
const STATE_PATH = process.env.N8N_SYNC_STATE_PATH || '/home/node/.n8n-files/notion-linear-sync/sync_state.json';
const CONFLICT_STRATEGY = process.env.CONFLICT_STRATEGY || 'last-write-wins';
const NOTION_VERSION = '2022-06-28';

function sha(data) { return crypto.createHash('sha256').update(JSON.stringify(data)).digest('hex').slice(0, 16); }
function ensureStateFile() { const dir = path.dirname(STATE_PATH); fs.mkdirSync(dir, { recursive: true }); if (!fs.existsSync(STATE_PATH)) fs.writeFileSync(STATE_PATH, JSON.stringify({ version: 1, entities: { project: [], milestone: [], task: [] } }, null, 2)); }
function loadState() { ensureStateFile(); try { return JSON.parse(fs.readFileSync(STATE_PATH, 'utf8')); } catch { return { version: 1, entities: { project: [], milestone: [], task: [] } }; } }
function saveState(state) { ensureStateFile(); fs.writeFileSync(STATE_PATH, JSON.stringify(state, null, 2)); }
function upsertState(state, record) { const bucket = state.entities.milestone || []; state.entities.milestone = bucket.filter((entry) => !(entry.notionId && entry.notionId === record.notionId) && !(entry.linearId && entry.linearId === record.linearId)); state.entities.milestone.push(record); }
async function notionRequest(endpoint, options = {}) { const response = await fetch(`https://api.notion.com/v1${endpoint}`, { ...options, headers: { Authorization: `Bearer ${NOTION_TOKEN}`, 'Notion-Version': NOTION_VERSION, 'Content-Type': 'application/json', ...(options.headers || {}) } }); const body = await response.json(); if (!response.ok) throw new Error(`Notion ${endpoint} failed: ${response.status} ${JSON.stringify(body)}`); return body; }
async function linearRequest(query, variables = {}) { const response = await fetch('https://api.linear.app/graphql', { method: 'POST', headers: { Authorization: LINEAR_API_KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ query, variables }) }); const body = await response.json(); if (!response.ok || body.errors) throw new Error(`Linear request failed: ${JSON.stringify(body.errors || body)}`); return body.data; }
const richText = (value) => value ? [{ text: { content: value } }] : [];
const title = (prop) => (prop?.title || []).map((entry) => entry.plain_text || entry.text?.content || '').join('').trim();
const rich = (prop) => (prop?.rich_text || []).map((entry) => entry.plain_text || entry.text?.content || '').join('').trim();
const dateValue = (prop) => prop?.date?.start || null;
const relationId = (prop) => prop?.relation?.[0]?.id || null;
const checkbox = (prop) => Boolean(prop?.checkbox);
function notionToUnified(page) { const props = page.properties || {}; const record = { notionId: page.id, linearId: rich(props['linear id']), name: title(props.milestone), description: rich(props.description), targetDate: dateValue(props['due date (manual)']) || dateValue(props['effective due date']), projectNotionId: relationId(props.project), updatedAt: page.last_edited_time, linearSync: checkbox(props['linear sync']) }; record.contentHash = sha({ name: record.name, description: record.description || '', targetDate: record.targetDate || null, projectNotionId: record.projectNotionId || null }); return record; }
function linearToUnified(milestone) { const record = { notionId: null, linearId: milestone.id, name: milestone.name, description: milestone.description || '', targetDate: milestone.targetDate || null, projectLinearId: milestone.project?.id || null, updatedAt: milestone.updatedAt, linearSync: true }; record.contentHash = sha({ name: record.name, description: record.description || '', targetDate: record.targetDate || null, projectLinearId: record.projectLinearId || null }); return record; }
async function fetchNotionMilestones() { let cursor; const records = []; do { const body = { page_size: 100, filter: { property: 'linear sync', checkbox: { equals: true } } }; if (cursor) body.start_cursor = cursor; const response = await notionRequest(`/databases/${NOTION_DB}/query`, { method: 'POST', body: JSON.stringify(body) }); records.push(...response.results.map(notionToUnified)); cursor = response.has_more ? response.next_cursor : null; } while (cursor); return records; }
async function fetchLinearMilestones() { const data = await linearRequest(`query Milestones { projectMilestones(first: 250) { nodes { id name description targetDate updatedAt project { id } } } }`); return (data.projectMilestones?.nodes || []).map(linearToUnified); }
function getStateFor(state, notionId, linearId) { return (state.entities.milestone || []).find((entry) => (notionId && entry.notionId === notionId) || (linearId && entry.linearId === linearId)) || null; }
function asMillis(value) { if (!value) return 0; const date = new Date(value); return Number.isNaN(date.getTime()) ? 0 : date.getTime(); }
function chooseWinner(notionRecord, linearRecord, state) { if (!state) return asMillis(notionRecord.updatedAt) >= asMillis(linearRecord.updatedAt) ? 'notion' : 'linear'; const notionChanged = asMillis(notionRecord.updatedAt) > asMillis(state.notionLastModified); const linearChanged = asMillis(linearRecord.updatedAt) > asMillis(state.linearLastModified); if (notionChanged && !linearChanged) return 'notion'; if (linearChanged && !notionChanged) return 'linear'; if (!notionChanged && !linearChanged) return 'none'; if (CONFLICT_STRATEGY === 'notion-primary') return 'notion'; if (CONFLICT_STRATEGY === 'linear-primary') return 'linear'; return asMillis(notionRecord.updatedAt) >= asMillis(linearRecord.updatedAt) ? 'notion' : 'linear'; }
function notionProps(record, projectNotionId) { return Object.fromEntries(Object.entries({ milestone: { title: [{ text: { content: record.name } }] }, 'linear id': { rich_text: richText(record.linearId) }, 'linear sync': { checkbox: true }, description: { rich_text: richText(record.description || '') }, project: projectNotionId ? { relation: [{ id: projectNotionId }] } : undefined, 'due date (manual)': record.targetDate ? { date: { start: record.targetDate } } : undefined }).filter(([, value]) => value !== undefined)); }
(async () => {
  const state = loadState();
  const projectStates = state.entities.project || [];
  const projectNotionToLinear = new Map(projectStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.notionId, entry.linearId]));
  const projectLinearToNotion = new Map(projectStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.linearId, entry.notionId]));
  const notionMilestones = await fetchNotionMilestones();
  const linearMilestones = await fetchLinearMilestones();
  const linearById = new Map(linearMilestones.map((record) => [record.linearId, record]));
  const touchedLinearIds = new Set();
  const summary = { success: true, entityType: 'milestone', createdToLinear: 0, updatedToLinear: 0, createdToNotion: 0, updatedToNotion: 0, milestonesCount: 0, errors: [] };

  for (const notionRecord of notionMilestones) {
    const linearRecord = notionRecord.linearId ? linearById.get(notionRecord.linearId) : undefined;
    const projectLinearId = projectNotionToLinear.get(notionRecord.projectNotionId);
    if (!projectLinearId) { summary.success = false; summary.errors.push(`missing project mapping for notion milestone ${notionRecord.notionId}`); continue; }
    if (!linearRecord) {
      try {
        const data = await linearRequest(`mutation CreateMilestone($input: ProjectMilestoneCreateInput!) { projectMilestoneCreate(input: $input) { success projectMilestone { id updatedAt } } }`, { input: { name: notionRecord.name, description: notionRecord.description || undefined, targetDate: notionRecord.targetDate || undefined, projectId: projectLinearId } });
        const milestone = data.projectMilestoneCreate.projectMilestone;
        await notionRequest(`/pages/${notionRecord.notionId}`, { method: 'PATCH', body: JSON.stringify({ properties: { 'linear id': { rich_text: richText(milestone.id) } } }) });
        upsertState(state, { entityType: 'milestone', notionId: notionRecord.notionId, linearId: milestone.id, notionLastModified: notionRecord.updatedAt, linearLastModified: milestone.updatedAt, contentHash: notionRecord.contentHash, lastSynced: new Date().toISOString() });
        summary.createdToLinear += 1;
      } catch (error) { summary.success = false; summary.errors.push(`create linear milestone ${notionRecord.notionId}: ${error.message}`); }
      continue;
    }
    touchedLinearIds.add(linearRecord.linearId);
    const stateRecord = getStateFor(state, notionRecord.notionId, linearRecord.linearId);
    if (notionRecord.contentHash === linearRecord.contentHash) { upsertState(state, { entityType: 'milestone', notionId: notionRecord.notionId, linearId: linearRecord.linearId, notionLastModified: notionRecord.updatedAt, linearLastModified: linearRecord.updatedAt, contentHash: notionRecord.contentHash, lastSynced: new Date().toISOString() }); continue; }
    const winner = chooseWinner(notionRecord, linearRecord, stateRecord);
    if (winner === 'notion') {
      try {
        const data = await linearRequest(`mutation UpdateMilestone($id: String!, $input: ProjectMilestoneUpdateInput!) { projectMilestoneUpdate(id: $id, input: $input) { success projectMilestone { id updatedAt } } }`, { id: linearRecord.linearId, input: { name: notionRecord.name, description: notionRecord.description || undefined, targetDate: notionRecord.targetDate || undefined } });
        const updated = data.projectMilestoneUpdate.projectMilestone;
        upsertState(state, { entityType: 'milestone', notionId: notionRecord.notionId, linearId: linearRecord.linearId, notionLastModified: notionRecord.updatedAt, linearLastModified: updated.updatedAt, contentHash: notionRecord.contentHash, lastSynced: new Date().toISOString() });
        summary.updatedToLinear += 1;
      } catch (error) { summary.success = false; summary.errors.push(`update linear milestone ${linearRecord.linearId}: ${error.message}`); }
    } else if (winner === 'linear') {
      try {
        const projectNotionId = projectLinearToNotion.get(linearRecord.projectLinearId);
        const page = await notionRequest(`/pages/${notionRecord.notionId}`, { method: 'PATCH', body: JSON.stringify({ properties: notionProps(linearRecord, projectNotionId) }) });
        upsertState(state, { entityType: 'milestone', notionId: notionRecord.notionId, linearId: linearRecord.linearId, notionLastModified: page.last_edited_time, linearLastModified: linearRecord.updatedAt, contentHash: linearRecord.contentHash, lastSynced: new Date().toISOString() });
        summary.updatedToNotion += 1;
      } catch (error) { summary.success = false; summary.errors.push(`update notion milestone ${notionRecord.notionId}: ${error.message}`); }
    }
  }

  for (const linearRecord of linearMilestones) {
    if (touchedLinearIds.has(linearRecord.linearId)) continue;
    try {
      const projectNotionId = projectLinearToNotion.get(linearRecord.projectLinearId);
      if (!projectNotionId) throw new Error(`missing notion project mapping for linear project ${linearRecord.projectLinearId}`);
      const page = await notionRequest('/pages', { method: 'POST', body: JSON.stringify({ parent: { database_id: NOTION_DB }, properties: notionProps(linearRecord, projectNotionId) }) });
      upsertState(state, { entityType: 'milestone', notionId: page.id, linearId: linearRecord.linearId, notionLastModified: page.last_edited_time, linearLastModified: linearRecord.updatedAt, contentHash: linearRecord.contentHash, lastSynced: new Date().toISOString() });
      summary.createdToNotion += 1;
    } catch (error) { summary.success = false; summary.errors.push(`create notion milestone ${linearRecord.linearId}: ${error.message}`); }
  }

  saveState(state);
  summary.milestonesCount = summary.createdToLinear + summary.updatedToLinear + summary.createdToNotion + summary.updatedToNotion;
  summary.status = summary.errors.length ? 'completed_with_errors' : 'success';
  summary.details = summary.errors.length ? summary.errors.join(' | ').slice(0, 1900) : `Milestones synced: ${summary.milestonesCount}`;
  process.stdout.write(JSON.stringify(summary));
})().catch((error) => { process.stdout.write(JSON.stringify({ success: false, entityType: 'milestone', status: 'failed', milestonesCount: 0, details: error.message.slice(0, 1900), errors: [error.message] })); process.exitCode = 1; });
NODE
